import{_ as a,o as n,c as t,a5 as e}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"44. 使用 stdin、stdout 和 stderr","description":"The Little Book of C 中文版 — 44. 使用 stdin、stdout 和 stderr","frontmatter":{"title":"44. 使用 stdin、stdout 和 stderr","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","05-输入输出与文件","中文"],"description":"The Little Book of C 中文版 — 44. 使用 stdin、stdout 和 stderr","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":44,"sidebarWeight":44,"alternateZh":"/posts/c教程/zh-CN/05-输入输出与文件/044-Working with stdin, stdout, and stderr","alternateEn":"/posts/c教程/en-US/05-Input Output and Files/044-Working with stdin, stdout, and stderr"},"headers":[],"relativePath":"posts/c教程/zh-CN/05-输入输出与文件/044-Working with stdin, stdout, and stderr.md","filePath":"posts/c教程/zh-CN/05-输入输出与文件/044-Working with stdin, stdout, and stderr.md","lastUpdated":1790163617000}'),p={name:"posts/c教程/zh-CN/05-输入输出与文件/044-Working with stdin, stdout, and stderr.md"};function i(o,s,d,l,c,r){return n(),t("div",null,[...s[0]||(s[0]=[e(`<p>[English version](/posts/c教程/en-US/05-Input Output and Files/044-Working with stdin, stdout, and stderr)</p><p>每个 C 程序都会自动启动并连接到您的环境、键盘、终端屏幕和错误控制台的三个开放流。它们是标准 I/O 流，使您的程序灵活且可编写脚本。</p><p>理解这三个流对于编写可以与文件、管道和其他程序交互的工具至关重要，这也是 Unix 风格设计的本质。</p><h4 id="三种标准流" tabindex="-1">三种标准流 <a class="header-anchor" href="#三种标准流" aria-label="Permalink to &quot;三种标准流&quot;">​</a></h4><table tabindex="0"><thead><tr><th>流</th><th>目的</th><th>典型器件</th><th>使用示例</th></tr></thead><tbody><tr><td><code>stdin</code></td><td>标准输入</td><td>键盘（或通过文件<code>&lt;</code>)</td><td><code>scanf</code>,<code>fgets</code></td></tr><tr><td><code>stdout</code></td><td>标准输出</td><td>屏幕（或文件通过<code>&gt;</code>)</td><td><code>printf</code>,<code>puts</code>,<code>fprintf(stdout, …)</code></td></tr><tr><td><code>stderr</code></td><td>标准错误</td><td>屏幕（与标准输出分开）</td><td><code>fprintf(stderr, …)</code></td></tr></tbody></table><p>这些都是类型<code>FILE *</code>。您可以将它们视为普通文件指针，读取、写入或重定向它们。</p><h4 id="基本示例" tabindex="-1">基本示例 <a class="header-anchor" href="#基本示例" aria-label="Permalink to &quot;基本示例&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    char name[50];</span></span>
<span class="line"><span>    printf(&quot;Enter your name: &quot;);</span></span>
<span class="line"><span>    fgets(name, sizeof(name), stdin);</span></span>
<span class="line"><span>    fprintf(stdout, &quot;Hello, %s&quot;, name);</span></span>
<span class="line"><span>    fprintf(stderr, &quot;Note: This is an example error message.\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Enter your name: Alice</span></span>
<span class="line"><span>Hello, Alice</span></span>
<span class="line"><span>Note: This is an example error message.</span></span></code></pre></div><h4 id="shell-中的重定向" tabindex="-1">Shell 中的重定向 <a class="header-anchor" href="#shell-中的重定向" aria-label="Permalink to &quot;Shell 中的重定向&quot;">​</a></h4><p>您可以分别重定向每个流：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./program &lt; input.txt &gt; output.txt 2&gt; errors.log</span></span></code></pre></div><p>-<code>&lt;</code>取代<code>stdin</code>（从文件读取输入） -<code>&gt;</code>取代<code>stdout</code>（将正常输出写入文件） -<code>2&gt;</code>取代<code>stderr</code>（将错误写入文件）</p><p>您还可以将它们组合起来：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./program &gt; all_output.txt 2&gt;&amp;1</span></span></code></pre></div><p>这会将输出流和错误流合并到一个文件中。</p><h4 id="从标准输入读取" tabindex="-1">从标准输入读取 <a class="header-anchor" href="#从标准输入读取" aria-label="Permalink to &quot;从标准输入读取&quot;">​</a></h4><p>您可以构建动态处理输入的程序，一次一行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    char line[100];</span></span>
<span class="line"><span>    printf(&quot;Enter text (Ctrl+D to stop):\\n&quot;);</span></span>
<span class="line"><span>    while (fgets(line, sizeof(line), stdin))</span></span>
<span class="line"><span>        printf(&quot;You said: %s&quot;, line);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>现在你的程序的行为就像一个 Unix 过滤器，它可以交替地从文件、管道或键盘输入中读取。</p><p>例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>echo &quot;hello&quot; | ./program</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You said: hello</span></span></code></pre></div><h4 id="写入-stdout-和-stderr" tabindex="-1">写入 stdout 和 stderr <a class="header-anchor" href="#写入-stdout-和-stderr" aria-label="Permalink to &quot;写入 stdout 和 stderr&quot;">​</a></h4><p><code>stdout</code>用于正常程序输出，而<code>stderr</code>用于错误消息或日志。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    fprintf(stdout, &quot;Everything is fine.\\n&quot;);</span></span>
<span class="line"><span>    fprintf(stderr, &quot;Warning: something might be wrong.\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>您可以抑制正常输出但保留错误：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./program &gt; /dev/null</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Warning: something might be wrong.</span></span></code></pre></div><h4 id="小代码-使用-stdin-stdout-的字计数器" tabindex="-1">小代码：使用 stdin/stdout 的字计数器 <a class="header-anchor" href="#小代码-使用-stdin-stdout-的字计数器" aria-label="Permalink to &quot;小代码：使用 stdin/stdout 的字计数器&quot;">​</a></h4><p>这个小程序模仿了 Unix 的简化版本<code>wc</code>命令。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;ctype.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int ch, words = 0, in_word = 0;</span></span>
<span class="line"><span>    while ((ch = getchar()) != EOF) {</span></span>
<span class="line"><span>        if (isspace(ch))</span></span>
<span class="line"><span>            in_word = 0;</span></span>
<span class="line"><span>        else if (!in_word) {</span></span>
<span class="line"><span>            in_word = 1;</span></span>
<span class="line"><span>            words++;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    printf(&quot;Word count: %d\\n&quot;, words);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>尝试：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>echo &quot;C is small but powerful&quot; | ./wordcount</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Word count: 4</span></span></code></pre></div><h4 id="混合标准输出和标准错误" tabindex="-1">混合标准输出和标准错误 <a class="header-anchor" href="#混合标准输出和标准错误" aria-label="Permalink to &quot;混合标准输出和标准错误&quot;">​</a></h4><p>有时您需要将进度记录到<code>stderr</code>同时将结果输出到<code>stdout</code>。这样，日志就不会污染实际数据。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    for (int i = 0; i &lt; 3; i++) {</span></span>
<span class="line"><span>        fprintf(stderr, &quot;Processing item %d...\\n&quot;, i + 1);</span></span>
<span class="line"><span>        fprintf(stdout, &quot;Item %d processed\\n&quot;, i + 1);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>单独重定向日志：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./program &gt; result.txt 2&gt; log.txt</span></span></code></pre></div><h4 id="冲洗缓冲器" tabindex="-1">冲洗缓冲器 <a class="header-anchor" href="#冲洗缓冲器" aria-label="Permalink to &quot;冲洗缓冲器&quot;">​</a></h4><p>输出流被缓冲，直到缓冲区已满或刷新时才会写入数据。为了确保输出立即出现：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fflush(stdout);  // flush output buffer</span></span></code></pre></div><p>这对于交互式程序很有用。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>这三个流为您的程序提供了灵活性：</p><ul><li>交互式工作（键盘/屏幕）</li><li>批量工作（文件输入/输出）</li><li>使用管道与其他工具连锁</li></ul><p>它们是 Unix 哲学的基础：做好一件事并且可以组合在一起的小程序。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>编写一个从 stdin 读取并仅打印包含给定关键字的行的程序。</li><li>如果未提供关键字，则将错误打印到 stderr。</li><li>使用重定向文件的输入和输出<code>&lt;</code>和<code>&gt;</code>.</li><li>将进度消息添加到 stderr 并将其重定向到单独的日志。</li><li>将所有内容组合成一个小型“过滤器”工具，用于处理来自管道的文本。</li></ol><p>和<code>stdin</code>,<code>stdout</code>， 和<code>stderr</code>，您的 C 程序成为无缝融入实际工作流程的工具，能够与文件、其他程序和用户等进行交互。接下来，您将探索缓冲 I/O，了解 C 库如何使用读取和写入缓冲区来优化性能<code>fgets</code>,<code>fputs</code>，等等。</p>`,55)])])}const g=a(p,[["render",i]]);export{u as __pageData,g as default};
